import{createContext,useContext,useEffect,useState}from'react';import{Product}from'../data/products';import{getCommerceSettings}from'../data/siteConfig';
type CartItem={product:Product;qty:number};type User={name:string;status:'guest'|'pending'|'approved';tier:string};
type StoreT={cart:CartItem[];saved:number[];compare:number[];recent:number[];user:User;addCart:(p:Product,q?:number)=>void;setQty:(id:number,q:number)=>void;remove:(id:number)=>void;toggleSave:(id:number)=>void;toggleCompare:(id:number)=>void;viewProduct:(id:number)=>void;login:(email:string)=>void;logout:()=>void;cartCount:number;toast:string;showToast:(s:string)=>void};
const C=createContext<StoreT>(null!);const load=(k:string,d:any)=>{try{return JSON.parse(localStorage.getItem(k)||'')||d}catch{return d}};
export function StoreProvider({children}:{children:React.ReactNode}){const[cart,setCart]=useState<CartItem[]>(()=>load('ms-cart',[]));const[saved,setSaved]=useState<number[]>(()=>load('ms-saved',[]));const[compare,setCompare]=useState<number[]>(()=>load('ms-compare',[]));const[recent,setRecent]=useState<number[]>(()=>load('ms-recent',[]));const[user,setUser]=useState<User>(()=>load('ms-user',{name:'Guest',status:'guest',tier:'Standard'}));const[toast,setToast]=useState('');useEffect(()=>localStorage.setItem('ms-cart',JSON.stringify(cart)),[cart]);useEffect(()=>localStorage.setItem('ms-saved',JSON.stringify(saved)),[saved]);useEffect(()=>localStorage.setItem('ms-compare',JSON.stringify(compare)),[compare]);useEffect(()=>localStorage.setItem('ms-recent',JSON.stringify(recent)),[recent]);useEffect(()=>localStorage.setItem('ms-user',JSON.stringify(user)),[user]);const showToast=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),2600)};const addCart=(p:Product,q=1)=>{setCart(c=>{const e=c.find(x=>x.product.id===p.id);return e?c.map(x=>x.product.id===p.id?{...x,qty:x.qty+q}:x):[...c,{product:p,qty:q}]});showToast(`${p.name} added to order`)};const setQty=(id:number,q:number)=>setCart(c=>q<1?c.filter(x=>x.product.id!==id):c.map(x=>x.product.id===id?{...x,qty:q}:x));const remove=(id:number)=>setCart(c=>c.filter(x=>x.product.id!==id));const toggleSave=(id:number)=>{setSaved(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);showToast('Saved products updated')};const toggleCompare=(id:number)=>{setCompare(s=>s.includes(id)?s.filter(x=>x!==id):s.length>=4?(showToast('Compare up to 4 products'),s):[...s,id]);};const viewProduct=(id:number)=>setRecent(r=>[id,...r.filter(x=>x!==id)].slice(0,12));const login=(email:string)=>{setUser({name:email.split('@')[0].replace(/[._]/g,' '),status:'approved',tier:getCommerceSettings().defaultTier});showToast('Welcome back')};const logout=()=>setUser({name:'Guest',status:'guest',tier:'Standard'});return <C.Provider value={{cart,saved,compare,recent,user,addCart,setQty,remove,toggleSave,toggleCompare,viewProduct,login,logout,cartCount:cart.reduce((a,x)=>a+x.qty,0),toast,showToast}}>{children}</C.Provider>}export const useStore=()=>useContext(C);
