import{Link,useParams,useSearchParams}from'react-router-dom';import{useState}from'react';import{ArrowRight,ShieldCheck,Truck,Clock3,MapPin,Heart,MessageCircle,Check,Store,PackageSearch,FileText,Search}from'lucide-react';import{brands,categories,products}from'../data/products';import ProductCard from'../components/ProductCard';import BrandLogo,{brandSlug}from'../components/BrandLogo';import{useStore}from'../context/Store';
const slug=(s:string)=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-');
export function BrandPage(){const{slug:brandSlug}=useParams();const brand=brands.find(b=>slug(b)===brandSlug)||brands[0];const list=products.filter(p=>p.brand===brand);const{showToast}=useStore();return <div className="brand-store"><div className="brand-cover"><div className="container"><div className="brand-mark"><BrandLogo brand={brand} variant="hero"/></div><div><p className="eyebrow">WHOLESALE BRAND SHOWROOM</p><h1>{brand}</h1><p>Browse available {brand} references prepared for qualified wholesale purchasing.</p><span>Trademark belongs to its respective owner · Relationship status requires verification</span></div><button onClick={()=>showToast('Brand saved to your account')}><Heart/> Follow brand</button></div></div><nav className="brand-nav"><div className="container"><a href="#products">Products</a><a href="#story">Brand information</a><a href="#terms">Wholesale terms</a><a href="#documents">Documents</a></div></nav><section className="brand-body container"><main><div className="brand-category-row"><b>Shop this brand</b>{[...new Set(list.map(p=>p.category))].map(x=><Link to={`/shop?brand=${encodeURIComponent(brand)}&category=${x}`} key={x}>{x}</Link>)}</div><div className="brand-feature"><div><span>FEATURED ASSORTMENT</span><h2>Retail-recognized products, organized for wholesale.</h2><p>Compare pack sizes, case quantities and protected pricing from one brand-focused workspace.</p><a href="#products">View wholesale assortment <ArrowRight/></a></div><div>{list.slice(0,3).map(p=><img key={p.id} src={p.image}/>)}</div></div><div id="products" className="brand-products-head"><div><p className="eyebrow">AVAILABLE PRODUCTS</p><h2>{list.length} wholesale listings</h2></div><select><option>Featured</option><option>Best selling</option><option>Newest</option></select></div><div className="product-grid brand-product-grid">{list.map(p=><ProductCard p={p} key={p.id}/>)}</div><section id="story" className="brand-story"><p className="eyebrow">BRAND INFORMATION</p><h2>About {brand}</h2><p>This showroom organizes products associated with the referenced trademark for wholesale discovery. Final brand descriptions, approved marketing assets and relationship claims should be supplied through the company’s authorized asset and legal-review process.</p><div><span><b>Primary categories</b>{[...new Set(list.map(p=>p.category))].join(', ')}</span><span><b>Catalog references</b>{list.length} listings</span><span><b>Inventory model</b>Case-level wholesale</span></div></section></main><aside id="terms" className="brand-terms"><h3>Wholesale ordering</h3>{[[PackageSearch,'Opening order',`From ${Math.min(...list.map(p=>p.moq))} case`],[Truck,'Ships from','United States inventory'],[Clock3,'Dispatch','Typically 2–7 business days'],[ShieldCheck,'Pricing','Approved accounts only']].map(([I,a,b]:any)=><div key={a}><I/><span><small>{a}</small><b>{b}</b></span></div>)}<Link className="btn dark full" to="/apply">Apply to view pricing</Link><Link className="btn inquiry full" to="/request-quote"><MessageCircle/> Request brand quote</Link><p>Terms shown are demonstration settings and remain subject to account and inventory verification.</p></aside></section></div>}
export function CategoryPage(){const{slug:catSlug}=useParams();const cat=categories.find(c=>slug(c)===catSlug)||categories[0];const list=products.filter(p=>p.category===cat);const related=categories.filter(x=>x!==cat).slice(0,6);return <div className="category-landing"><section className="category-hero"><div className="container"><div><p>HOME / CATEGORIES / {cat.toUpperCase()}</p><h1>{cat} wholesale marketplace</h1><span>Explore products, brands, case packs and sourcing options for qualified business buyers.</span><Link className="btn primary" to={`/shop?category=${encodeURIComponent(cat)}`}>Browse all {cat.toLowerCase()} <ArrowRight/></Link></div><div className="category-hero-products">{list.slice(0,3).map(p=><img src={p.image} key={p.id}/>)}</div></div></section><section className="category-content container"><aside><b>Browse beauty categories</b>{categories.map(x=><Link className={x===cat?'active':''} to={`/category/${slug(x)}`} key={x}>{x}<span>›</span></Link>)}</aside><main><section className="category-paths"><div className="section-title"><h2>Explore {cat}</h2><Link to={`/shop?category=${cat}`}>View all products →</Link></div><div>{['Best sellers','New arrivals','Ready to ship','Low minimums','Premium assortment','Volume opportunities'].map((x,i)=><Link to={`/shop?category=${cat}`} key={x}><span>{String(i+1).padStart(2,'0')}</span><b>{x}</b><small>Discover products</small></Link>)}</div></section><section className="category-rankings"><div className="section-title"><h2>Popular in {cat}</h2></div><div className="product-grid">{list.slice(0,8).map(p=><ProductCard p={p} key={p.id}/>)}</div></section><section className="category-brands"><div className="section-title"><h2>Featured brands</h2></div><div>{[...new Set(list.map(p=>p.brand))].map(b=><Link to={`/brand/${slug(b)}`} key={b}><BrandLogo brand={b} variant="compact"/><b>{b}</b><small>{list.filter(p=>p.brand===b).length} listings</small></Link>)}</div></section><section className="buying-guide"><div><p className="eyebrow">CATEGORY BUYING GUIDE</p><h2>Build a commercially balanced {cat.toLowerCase()} assortment.</h2></div><div>{[['Compare unit economics','Review wholesale price, MSRP, case pack and expected margin together.'],['Plan opening quantities','Use MOQ and volume tiers to balance assortment breadth with inventory depth.'],['Verify documentation','Confirm product, batch and brand-relationship documentation where required.'],['Build replenishment rules','Use saved products and reorder tools to maintain proven sellers.']].map(([a,b],i)=><article key={a}><span>0{i+1}</span><h3>{a}</h3><p>{b}</p></article>)}</div></section></main></section><section className="related-categories container"><div className="section-title"><h2>Continue exploring</h2></div><div>{related.map(x=><Link to={`/category/${slug(x)}`} key={x}>{x}<ArrowRight/></Link>)}</div></section></div>}
export function SupplierDirectory(){const[params]=useSearchParams();const[q,setQ]=useState(params.get('q')||'');const entries=[['Meridian Supply Co.','Multi-category wholesale distribution','United States','Nearly 30 years*'],['Northstar Beauty Partners','Professional beauty assortment','United States','Demo profile'],['Atelier Trade Group','Premium fragrance sourcing','United States','Demo profile'],['Common Market Supply','General merchandise and gifting','United States','Demo profile']].filter(e=>(e[0]+' '+e[1]).toLowerCase().includes(q.toLowerCase()));return <div className="supplier-directory"><section className="info-hero"><div className="container"><span className="eyebrow">SUPPLIER DISCOVERY</span><h1>Find wholesale supply partners.</h1><p>Compare categories, capabilities, locations and account services before starting a conversation.</p></div></section><div className="supplier-directory-search container"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search supplier name or specialization"/>{q&&<button onClick={()=>setQ('')}>Clear</button>}</div><div className="container supplier-dir-layout"><aside><h3>Filter suppliers</h3>{['Verified profile','United States inventory','Ready to ship','Accepts RFQs','Provides documents','Sample program','Payment terms eligible'].map(x=><label key={x}><input type="checkbox"/>{x}</label>)}</aside><main><div className="supplier-dir-toolbar"><b>{entries.length} supplier profiles</b><select><option>Best match</option><option>Response time</option><option>Product count</option></select></div>{entries.map((e,i)=><article key={e[0]}><div className="dir-logo">{e[0].split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><h2>{e[0]} {i===0&&<span><ShieldCheck/> Verified profile</span>}</h2><p>{e[1]}</p><div><span><MapPin/> {e[2]}</span><span><Clock3/> {e[3]}</span><span><Store/> Wholesale supplier</span></div><div className="dir-tags"><b>Fragrance</b><b>Skincare</b><b>Makeup</b><b>Domestic inventory</b></div></div><div className="dir-actions"><Link className="btn dark" to={i===0?'/supplier/meridian':'/supplier/meridian'}>View profile</Link><Link to="/supplier/meridian"><MessageCircle/> Contact</Link></div></article>)}</main></div></div>}

export function BrandDirectory(){const[params]=useSearchParams();const initial=params.get('q')||'';const[q,setQ]=useState(initial);const[category,setCategory]=useState('All categories');const[letter,setLetter]=useState('All');const{showToast}=useStore();const records=brands.map(name=>{const list=products.filter(p=>p.brand===name);return{name,list,categories:[...new Set(list.map(p=>p.category))],featured:list.some(p=>p.tags.includes('Best Seller'))}}).filter(b=>(!q||b.name.toLowerCase().includes(q.toLowerCase()))&&(category==='All categories'||b.categories.includes(category))&&(letter==='All'||b.name[0].toUpperCase()===letter));return <div className="brand-directory-page"><section className="brand-directory-hero"><div className="container"><span className="eyebrow">WHOLESALE BRAND DISCOVERY</span><h1>Discover brands for every assortment.</h1><p>Search the complete multi-category brand portfolio, compare available products and open brand-specific wholesale showrooms.</p><div className="brand-directory-search"><Search/><input autoFocus={!!initial} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search brand name"/>{q&&<button onClick={()=>setQ('')}>Clear</button>}</div><div className="brand-directory-stats"><span><b>{brands.length}</b>brands</span><span><b>{products.length}</b>product listings</span><span><b>{categories.length}</b>categories</span></div></div></section><div className="brand-directory-tools container"><div className="brand-alphabet">{['All',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(x=><button className={letter===x?'active':''} onClick={()=>setLetter(x)} key={x}>{x}</button>)}</div><div className="brand-category-filter"><label>Category<select value={category} onChange={e=>setCategory(e.target.value)}><option>All categories</option>{categories.map(c=><option key={c}>{c}</option>)}</select></label><span>{records.length} results</span></div></div><section className="brand-directory-grid container">{records.length?records.map(b=><article key={b.name}><div className="brand-wordmark"><BrandLogo brand={b.name} variant="card"/>{b.featured&&<b>FEATURED</b>}</div><div className="brand-directory-copy"><div><h2>{b.name}</h2><button onClick={()=>showToast(`${b.name} added to followed brands`)}><Heart/>Follow</button></div><p>{b.categories.slice(0,3).join(' · ')}</p><div className="brand-directory-metrics"><span><b>{b.list.length}</b>products</span><span><b>{b.list.filter(p=>p.stock>0).length}</b>available</span><span><b>{Math.min(...b.list.map(p=>p.moq))}</b>case MOQ</span></div><div className="brand-product-preview">{b.list.slice(0,3).map(p=><Link key={p.id} to={'/products/'+p.slug}><img src={p.image} alt={p.name} loading="lazy"/></Link>)}</div><Link className="brand-open" to={'/brand/'+b.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}>Open wholesale showroom <ArrowRight/></Link></div></article>):<div className="listing-empty"><h2>No brands match your search</h2><p>Clear the filters or try another brand name.</p><button className="btn outline" onClick={()=>{setQ('');setCategory('All categories');setLetter('All')}}>Clear all filters</button></div>}</section><section className="brand-asset-notice container"><ShieldCheck/><div><b>Brand asset and relationship controls</b><p>Text-based wordmarks are used when approved official logos are unavailable. Trademark ownership and verified distribution relationships should be configured only from supplied legal documentation.</p></div></section></div>}
